// @ts-nocheck
// Parity test: the TS port in ./metadata.ts must produce exactly what the legacy
// legacy/src/utils/metadata.js produced for the same inputs.
//
// The expected values in ./__fixtures__/metadata/*.json were generated by running the legacy
// module itself (see ../scripts/legacy/gen-metadata-fixtures.ts); the inputs live in ./__fixtures__/metadata/cases.ts.
import { describe, expect, test } from 'bun:test';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import * as M from './metadata';
import * as version from './version';
import { buildCases, runCases, exportNames } from './__fixtures__/metadata/cases';

const dir = join(import.meta.dir, '__fixtures__/metadata');
const load = (name) => JSON.parse(readFileSync(join(dir, name + '.json'), 'utf8'));

describe('version', () => {
	const golden = load('version');

	test('exports the same names as legacy', () => {
		expect(Object.keys(version).sort()).toEqual(golden.exports);
	});

	test('exports the same values as legacy', () => {
		expect({ ...version }).toEqual(golden.values);
	});
});

describe('metadata', () => {
	test('exports the same names as legacy', () => {
		expect(Object.keys(M).sort()).toEqual(load('exports'));
		expect(Object.keys(M).sort()).toEqual(exportNames.slice().sort());
	});

	test('every export is covered by at least one case', () => {
		const covered = new Set(buildCases().map((c) => (Array.isArray(c.fn) ? c.fn[0] : c.fn)));
		expect([...covered].sort()).toEqual(exportNames.slice().sort());
	});

	const actual = runCases(M);

	test('fixtures and cases are in sync', () => {
		const files = readdirSync(dir)
			.filter((f) => f.endsWith('.json'))
			.map((f) => f.replace(/\.json$/, ''))
			.filter((f) => f !== 'version' && f !== 'exports')
			.sort();

		expect(files).toEqual(Object.keys(actual).sort());

		for (const group of files) {
			expect(Object.keys(load(group))).toEqual(Object.keys(actual[group]));
		}
	});

	for (const group in actual) {
		describe(group, () => {
			const golden = load(group);

			for (const name in actual[group]) {
				test(name, () => {
					expect(actual[group][name]).toEqual(golden[name]);
				});
			}
		});
	}
});

describe('metadata does not share state between calls', () => {
	test('defaults are deep copies', () => {
		const a = M.getDefaultIngestMetadata();
		a.control.hls.listSize = 99;
		a.profiles.push({});
		expect(M.getDefaultIngestMetadata().control.hls.listSize).toBe(6);
		expect(M.getDefaultIngestMetadata().profiles).toEqual([{}]);

		const b = M.getDefaultEgressMetadata();
		b.control.process.delay = 99;
		expect(M.getDefaultEgressMetadata().control.process.delay).toBe(15);

		const c = M.getDefaultMetadata();
		c.playersite.x = 1;
		expect(M.getDefaultMetadata().playersite).toEqual({});
	});

	test('init*Metadata results do not alias the defaults', () => {
		const a = M.initIngestMetadata();
		a.control.hls.listSize = 99;
		a.meta.author.name = 'x';
		expect(M.initIngestMetadata().control.hls.listSize).toBe(6);
		expect(M.initIngestMetadata().meta.author.name).toBe('');

		const b = M.initEgressMetadata();
		b.control.source.source = 'x';
		expect(M.initEgressMetadata().control.source.source).toBe('hls+memfs');
	});
});
